const esc = value => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
const icon = (name, className = '') => `<svg class="icon ${className}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({ arrow: '<path d="M7 17 17 7M7 7h10v10"/>', right: '<path d="M5 12h14m-6-6 6 6-6 6"/>', sun: '<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41m0-14.14-1.41 1.41M6.34 17.66l-1.41 1.41"/>', moon: '<path d="M20.9 13.1A9 9 0 0 1 10.9 3.1 9 9 0 1 0 20.9 13.1Z"/>', menu: '<path d="M4 6h16M4 12h16M4 18h16"/>', mail: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>', download: '<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>', search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', code: '<path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-11-2 14"/>', brain: '<path d="M12 5a3 3 0 0 0-5-2 3 3 0 0 0-3 5 4 4 0 0 0 0 7 3 3 0 0 0 3 5 3 3 0 0 0 5-2V5Zm0 0a3 3 0 0 1 5-2 3 3 0 0 1 3 5 4 4 0 0 1 0 7 3 3 0 0 1-3 5 3 3 0 0 1-5-2M8 7v3H5m11-3v3h3M8 15h2m4 0h2"/>', network: '<circle cx="12" cy="5" r="2"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/><path d="M12 7v5M5 17v-5h14v5"/>', growth: '<path d="m4 17 6-6 4 4 6-10M14 5h6v6"/>', copy: '<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>' })[name] || ''}</svg>`;
const brand = (id, monochrome = false) => `<img class="brand-icon${monochrome ? ' monochrome' : ''}" src="/assets/icons/${esc(id)}.svg" width="26" height="26" alt="" loading="lazy">`;
const button = (href, label, primary = false, extra = '') => `<a class="button${primary ? ' primary' : ''}" href="${esc(href)}" ${extra}>${esc(label)}${icon('arrow')}</a>`;
const intro = (title, text, extra = '') => `<header class="page-intro"><h1>${title}</h1><p>${esc(text)}</p>${extra}</header>`;
const evidenceLabels = { 'Additional familiarity':'Additional Familiarity', 'Used in a project':'Used in a Project', 'Used in this portfolio':'Used in This Portfolio', 'Present in project source':'Present in Project Source', 'Listed in my résumé':'Listed in My Résumé' };
const tagList = (ids, technologies, icons = false) => `<ul class="tags" aria-label="Technologies">${ids.map(id => technologies.find(tech => tech.id === id)).filter(Boolean).map(tech => `<li>${icons ? brand(tech.iconId || tech.id, ['express','socketio'].includes(tech.id)) : ''}${esc(tech.name)}</li>`).join('')}</ul>`;
const portrait = (profile, eager = false) => profile.portrait ? `<img class="portrait" src="${esc(profile.portrait)}" srcset="/assets/personal/ej-portrait-400.webp 400w, ${esc(profile.portrait)} 800w" sizes="(max-width: 767px) min(400px, calc(100vw - 82px)), (max-width: 1023px) 36vw, 400px" width="800" height="1067" alt="EJ Christian Medilo wearing a cap and black hoodie" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'}>` : '<span class="portrait initials" aria-label="EJ’s initials">EJ</span>';
const wordmark = () => `<img class="logo-avatar" src="/assets/personal/ej-avatar.webp" width="34" height="34" alt=""><span>EJ Medilo<span class="wordmark-dot">.</span></span>`;
const sectionTitle = (label, ghost = label) => `<div class="reference-heading"><span class="heading-ghost" aria-hidden="true">${esc(ghost)}</span><h2>${esc(label)}</h2></div>`;
const processStages = [
  ['Record', 'Record the violation and keep its context in one place.'],
  ['Service', 'Connect the record to an assigned service and its required hours.'],
  ['Attendance', 'Capture time in and time out through the QR attendance workflow.'],
  ['Clearance', 'Use recorded attendance for DTR credit and the clearance workflow.']
];

function screenImage(screen, eager = false, compact = false) {
  const responsive = screen.srcSmall && screen.smallWidth < screen.width ? ` srcset="${esc(screen.srcSmall)} ${screen.smallWidth}w, ${esc(screen.src)} ${screen.width}w" sizes="${compact ? (screen.kind === 'mobile' ? '(max-width: 899px) 32vw, 180px' : '(max-width: 899px) calc(100vw - 96px), 560px') : screen.kind === 'mobile' ? '(max-width: 767px) 60vw, 280px' : '(max-width: 767px) 85vw, 900px'}"` : '';
  return `<img src="${esc(screen.src)}"${responsive} width="${screen.width}" height="${screen.height}" alt="${esc(screen.alt)}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'}>`;
}
function deviceScreen(screen, eager = false, compact = false) {
  const image=screenImage(screen,eager,compact);
  if(screen.deviceFrame)return image;
  if(screen.kind==='desktop')return `<span class="monitor-frame"><span class="monitor-display">${image}</span></span>`;
  return `<span class="phone-frame">${image}</span>`;
}
function projectVisual(project, hero = false) {
  const prefix = `picture-${project.id}`;
  return `<section class="picture-deck ${project.id}${hero ? ' card card--media' : ''}" data-deck data-deck-kind="project" data-picture-deck data-platform="${project.platform.toLowerCase()}" aria-label="${esc(project.title)} Screenshots"><div class="picture-stage" data-deck-stage data-tilt>${project.previewScreens.map((screen,index) => `<figure class="picture-panel" data-deck-card><div class="picture-media ${screen.kind === 'mobile' ? 'portrait-media' : 'desktop-media'}" data-deck-media>${deviceScreen(screen,hero && index === 0)}</div><figcaption id="${prefix}-${esc(screen.id)}" data-deck-caption><h3>${esc(screen.label)}</h3>${screen.presentationLabel ? `<p class="preview-provenance">${esc(screen.presentationLabel)}</p>` : ''}<p>${esc(screen.explanation)}</p><p class="small muted">${esc(screen.caption)}</p><div class="picture-image-links"><a href="${esc(screen.src)}">View Full Image ${icon('arrow')}</a>${screen.originalSrc ? `<a href="${esc(screen.originalSrc)}">Original Capture ${icon('arrow')}</a>` : ''}</div></figcaption></figure>`).join('')}</div><div class="picture-controls" data-deck-controls hidden><div class="picture-arrows"><button type="button" class="icon-button" data-deck-prev aria-label="Previous ${esc(project.title)} image">←</button><p data-deck-counter role="status"></p><button type="button" class="icon-button" data-deck-next aria-label="Next ${esc(project.title)} image">→</button></div><div class="picture-selectors" role="group" aria-label="Choose ${esc(project.title)} screen">${project.previewScreens.map((screen,index)=>`<button type="button" data-deck-select data-deck-index="${index}" aria-controls="${prefix}-${esc(screen.id)}" aria-pressed="${index===0}">${esc(screen.label)}</button>`).join('')}</div></div></section>`;
}

function projectDetailsViewer(projects, technologies) {
  const detailProject=projects.find(project=>project.id==='sti-vio-log');
  return '<dialog class="project-viewer project-details-viewer" id="project-details-viewer" data-project-viewer aria-labelledby="project-details-title"><header class="preview-header"><div class="project-dialog-heading"><img data-project-thumbnail src="'+esc(detailProject.previewScreens[0].srcSmall)+'" width="38" height="38" alt=""><div><p>Project Details</p><h2 id="project-details-title" data-project-title>'+esc(detailProject.title)+'</h2></div></div><div class="project-dialog-actions"><span class="project-details-featured" data-project-featured><i aria-hidden="true"></i> Featured</span><button class="icon-button" type="button" data-preview-close aria-label="Close Project Details" autofocus>✕</button></div></header>'+projects.filter(project=>project.id==='sti-vio-log').map((project,index)=>{
    const prefix='preview-'+project.id;
    const category=project.platform==='Web'?'Full-Stack Web Application':'Android Application';
    const more=projects.filter(other=>other.id!==project.id);
    return '<section data-project-panel="'+esc(project.id)+'" data-project-title="'+esc(project.title)+'" data-project-featured="'+(index===0)+'"'+(index?' hidden':'')+'><div class="project-details-main"><div class="project-gallery-column">'+project.previewScreens.map((screen,i)=>'<figure id="'+prefix+'-'+esc(screen.id)+'" data-preview-slide'+(i?' hidden':'')+'><div class="preview-artwork"><img class="preview-ambient" src="'+esc(screen.srcSmall)+'" width="960" height="540" alt="" aria-hidden="true" loading="lazy"><img class="preview-image" src="'+esc(screen.src)+'" width="'+screen.width+'" height="'+screen.height+'" alt="'+esc(screen.alt)+'" loading="lazy"></div><figcaption><h4>'+esc(screen.label)+'</h4><p class="preview-provenance">'+esc(screen.presentationLabel)+' · '+esc(screen.caption)+'</p><a class="preview-full-image" href="'+esc(screen.src)+'" target="_blank" rel="noopener noreferrer">View Full Image<span class="sr-only"> (opens in a new tab)</span> '+icon('arrow')+'</a></figcaption></figure>').join('')+'<div class="preview-navigation"><button class="icon-button" type="button" data-preview-prev aria-label="Previous Screenshot">←</button><p data-preview-count role="status" aria-live="polite">1 / '+project.previewScreens.length+'</p><button class="icon-button" type="button" data-preview-next aria-label="Next Screenshot">→</button></div><div class="preview-thumbnails" role="group" aria-label="Choose '+esc(project.title)+' screenshot">'+project.previewScreens.map((screen,i)=>'<button type="button" class="preview-thumbnail" data-preview-select data-preview-index="'+i+'" aria-controls="'+prefix+'-'+esc(screen.id)+'" aria-pressed="'+(i===0)+'"><img src="'+esc(screen.srcSmall)+'" width="960" height="540" alt="" loading="lazy"><span>'+esc(screen.label)+'</span></button>').join('')+'</div></div><div class="project-details-copy"><div class="project-detail-labels"><span>'+esc(project.platform)+' Application</span>'+(index===0?'<span class="project-details-featured"><i aria-hidden="true"></i> Featured</span>':'')+'</div><h3>'+esc(project.title)+'</h3><p class="project-summary">'+esc(project.summary)+'</p><dl class="project-details-facts"><div><dt>Category</dt><dd>'+esc(category)+'</dd></div><div><dt>Status</dt><dd>'+esc(project.status)+'</dd></div><div><dt>Tools</dt><dd>'+tagList(project.cardTechnologies,technologies,true)+'</dd></div></dl><div class="actions">'+(project.liveUrl?button(project.liveUrl,'Live Preview',true):button(project.sourceUrl,'Source Code',true))+button('/contact/','Contact Me')+'<a class="text-link" href="/projects/'+esc(project.id)+'/">Case Study '+icon('arrow')+'</a>'+(project.liveUrl?'<a class="text-link" href="'+esc(project.sourceUrl)+'">Source Code '+icon('arrow')+'</a>':'')+'</div></div></div><footer class="project-more-work"><p class="eyebrow">Up Next</p><h3>/More Work</h3><div class="more-work-grid">'+more.map(other=>'<a class="more-project" href="/projects/'+esc(other.id)+'/" aria-label="View '+esc(other.title)+' Project Details"><img src="'+esc(other.previewScreens[0].srcSmall)+'" width="960" height="640" alt="" loading="lazy"><div><h4>'+esc(other.title)+'</h4><p>'+esc(other.platform)+' Application</p><span>View '+icon('arrow')+'</span></div></a>').join('')+'</div></footer></section>';
  }).join('')+'</dialog>';
}

function projectViewer(project) {
  const id = `preview-${project.id}`;
  return `<dialog class="project-viewer" id="${id}" aria-labelledby="${id}-title"><header class="preview-header"><h2 id="${id}-title">${esc(project.title)} Screenshots</h2><button class="icon-button" type="button" data-preview-close aria-label="Close Screenshot Preview" autofocus>✕</button></header><div class="preview-body">${project.previewScreens.map((screen,index)=>`<figure id="${id}-${esc(screen.id)}" data-preview-slide${index ? ' hidden' : ''}><img class="preview-image" src="${esc(screen.src)}" width="${screen.width}" height="${screen.height}" alt="${esc(screen.alt)}" loading="lazy"><figcaption><h3>${esc(screen.label)}</h3>${screen.presentationLabel ? `<p class="preview-provenance">${esc(screen.presentationLabel)}</p>` : ''}<p>${esc(screen.caption)}</p><div class="picture-image-links"><a href="${esc(screen.src)}" target="_blank" rel="noopener noreferrer">View Full Image<span class="sr-only"> (opens in a new tab)</span> ${icon('arrow')}</a>${screen.originalSrc ? `<a href="${esc(screen.originalSrc)}" target="_blank" rel="noopener noreferrer">Original Capture<span class="sr-only"> (opens in a new tab)</span> ${icon('arrow')}</a>` : ''}</div></figcaption></figure>`).join('')}<div class="preview-navigation"><button class="icon-button" type="button" data-preview-prev aria-label="Previous Screenshot">←</button><p data-preview-count role="status" aria-live="polite">1 / ${project.previewScreens.length}</p><button class="icon-button" type="button" data-preview-next aria-label="Next Screenshot">→</button></div><div class="preview-thumbnails" role="group" aria-label="Choose ${esc(project.title)} screenshot">${project.previewScreens.map((screen,index)=>`<button type="button" class="preview-thumbnail" data-preview-select data-preview-index="${index}" aria-controls="${id}-${esc(screen.id)}" aria-pressed="${index===0}"><img src="${esc(screen.srcSmall || screen.src)}" width="${screen.smallWidth || screen.width}" height="${Math.round(screen.height * (screen.smallWidth || screen.width) / screen.width)}" alt="" loading="lazy"><span>${esc(screen.label)}</span></button>`).join('')}</div></div></dialog>`;
}

function projectCard(project, technologies, index) {
  return projectFeature(project, technologies, index, true);
}


function githubBlock(compact = false) {
  return `<section class="github-panel card" data-github aria-busy="false"><div class="github-heading"><div><h${compact ? '3' : '2'}>A Public Record of the Work</h${compact ? '3' : '2'}><p data-github-status role="status">Explore the source, commits, and project documentation on GitHub.</p></div><a class="button" href="https://github.com/Eyzen08">${brand('github', true)}Eyzen08${icon('arrow')}</a></div><div class="github-stats" data-github-stats hidden><p><strong data-repos></strong><span>Public Repositories</span></p><p><strong data-followers></strong><span>Followers</span></p></div><div class="contribution-card"><div class="contribution-heading"><div><h${compact ? '4' : '3'}>Contribution Activity</h${compact ? '4' : '3'}><p class="calendar-label" data-calendar-label>Contribution calendar available on GitHub.</p></div><a class="calendar-profile" href="https://github.com/Eyzen08?tab=overview">View on GitHub ${icon('arrow')}</a></div><div data-calendar-section hidden><div class="calendar-legend"><span>Less</span><i class="level-0"></i><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><span>More</span></div><div class="calendar-scroll" tabindex="0" role="region" aria-label="Contribution calendar"><div class="calendar" data-calendar aria-hidden="true"></div></div><details class="daily-details"><summary>Read Daily Contribution Counts</summary><div class="daily-scroll"><table><thead><tr><th scope="col">Date</th><th scope="col">Contributions</th></tr></thead><tbody data-calendar-days></tbody></table></div></details></div></div><ul class="event-list" data-events></ul>${compact ? '' : '<p class="small muted">Contributions include more than commits. GitHub’s public event feed can be delayed or incomplete.</p>'}<button type="button" class="text-button" data-github-retry>Refresh Activity</button></section>`;
}

function timeline(entries, headingLevel = 3) {
  return `<div class="timeline">${entries.map(item => `<article><span class="timeline-date">${esc(item.period)}</span><div><h${headingLevel}>${esc(item.title)}</h${headingLevel}>${item.organization ? `<p class="organization">${esc(item.organization)}</p>` : ''}${item.location ? `<p class="small">${esc(item.location)}</p>` : ''}${item.text ? `<p>${esc(item.text)}</p>` : ''}${item.bullets?.length ? `<ul class="experience-bullets">${item.bullets.map(text => `<li>${esc(text)}</li>`).join('')}</ul>` : ''}</div></article>`).join('')}</div>`;
}

function filterControls(categories, noun) {
  return `<div class="filter-controls" data-filter-controls hidden><label class="search-field">${icon('search')}<span class="sr-only">Search ${noun[0].toUpperCase()+noun.slice(1)}</span><input type="search" placeholder="Search ${noun[0].toUpperCase()+noun.slice(1)}" autocomplete="off"></label><div class="filter-buttons" role="group" aria-label="${noun} categories"><button type="button" data-category="all" aria-pressed="true">All</button>${categories.map(category => `<button type="button" data-category="${esc(category)}" aria-pressed="false">${esc(category)}</button>`).join('')}</div><p class="result-count" data-result-count role="status"></p></div>`;
}

const emptyState = '<div class="empty-state" data-empty hidden><h2>No Matches This Time.</h2><p>Try a different word or category.</p><button type="button" class="button" data-reset>Clear Filters</button></div>';

function architecture(project) {
  const nodes = project.id === 'sti-vio-log' ? [['React + Vite', 'Browser Interface'], ['Express + Socket.IO', 'API and Scoped Communication'], ['PostgreSQL', 'Managed through Supabase']] : [['Java + XML', 'Native Android Screens'], ['SharedPreferences', 'Local Progression'], ['Firebase Database', 'Custom Account Data']];
  return `<figure class="architecture"><div>${nodes.map(([title, detail], index) => `<div class="architecture-node"><strong>${esc(title)}</strong><span>${esc(detail)}</span></div>${index < nodes.length - 1 ? '<span class="architecture-connector" aria-hidden="true">↔</span>' : ''}`).join('')}</div><figcaption>${project.id === 'sti-vio-log' ? 'Frontend on Vercel, API on Render, and managed PostgreSQL on Supabase.' : 'Gameplay state and account data have separate storage responsibilities.'}</figcaption></figure>`;
}

function caseStudy(project, technologies) {
  return `${intro(esc(project.title), project.summary, `<div class="project-meta"><span>${esc(project.platform)} Application</span><span>${esc(project.year)}</span></div><div class="actions">${button(project.sourceUrl, 'View Source Code', true)}${project.liveUrl ? button(project.liveUrl, 'Open Live Platform') : ''}</div>`)}<div class="case-role card"><span>My Role</span><p>${esc(project.roleDetail)}</p></div>${projectVisual(project, true)}<div class="case-layout"><aside class="case-outline"><details open><summary>On This Page</summary><nav aria-label="Case study sections">${project.sections.map(section => `<a href="#${esc(section.id)}">${esc(section.title)}</a>`).join('')}</nav></details></aside><div class="case-content">${project.sections.map(section => `<section class="card" id="${esc(section.id)}"><h2>${esc(section.title)}</h2>${section.paragraphs.map(paragraph => `<p>${esc(paragraph)}</p>`).join('')}${section.bullets?.length ? `<ul>${section.bullets.map(item => `<li>${esc(item)}</li>`).join('')}</ul>` : ''}${section.id === 'architecture' ? architecture(project) : ''}${section.id === 'features' && project.id === 'sti-vio-log' ? `<ol class="process-list">${processStages.map(([label, text]) => `<li><strong>${label}</strong><span>${esc(text)}</span></li>`).join('')}</ol>` : ''}</section>`).join('')}<section class="card" id="technology"><h2>Technology in Context</h2>${tagList(project.technologies, technologies)}<a class="text-link" href="/stack/">Explore the Stack ${icon('right')}</a></section></div></div><div class="case-next"><a href="/projects/">${icon('right')} All Projects</a><a href="/projects/${project.id === 'sti-vio-log' ? 'kwiztorya' : 'sti-vio-log'}/">Next Case Study ${icon('arrow')}</a></div>`;
}

function resumePage(profile, projects, technologies) {
  const skills = technologies.filter(tech => tech.name !== 'Node test runner');
  const categories = [...new Set(skills.map(tech => tech.category))];
  return `${intro('Experience,<br>at a Glance.', profile.positioning, `<div class="actions">${profile.resumePdf ? button(profile.resumePdf, 'Download Résumé', true, 'download') : '<span class="pdf-pending">Updated PDF awaiting approval</span>'}<button class="button" type="button" data-print>Print Résumé ${icon('download')}</button></div>`)}<article class="resume-document"><header class="print-identity"><h2>${esc(profile.name)}</h2><p>${esc(profile.positioning)} · ${esc(profile.location)}</p><a href="mailto:${esc(profile.email)}">${esc(profile.email)}</a></header><div class="resume-layout"><div class="resume-main"><section class="card"><h2>Professional Summary</h2><p>${esc(profile.summary)}</p><p>${esc(profile.intro)}</p></section><section class="card"><h2>Selected Development Experience</h2>${projects.map(project => `<article class="resume-project"><div><h3><a href="/projects/${project.id}/">${esc(project.title)}</a></h3><span>${esc(project.year)}</span></div><p class="organization">${esc(project.role)}</p><p>${esc(project.summary)}</p>${tagList(project.cardTechnologies, technologies)}</article>`).join('')}</section><section class="card" id="experience"><h2>Experience</h2>${timeline(profile.experience)}</section><section class="card" id="education"><h2>Education</h2>${timeline(profile.education)}</section><section class="card" id="certifications"><h2>Certifications and Professional Development</h2>${timeline(profile.certifications)}</section></div><aside class="resume-sidebar" aria-label="Skills and contact"><section class="card" id="skills"><h2>Technical Skills</h2>${categories.map(category => `<div class="resume-skill-group"><h3>${esc(category)}</h3><p>${skills.filter(tech => tech.category === category && tech.label !== 'Additional familiarity').map(tech => esc(tech.name)).join(', ')}</p>${skills.some(tech => tech.category === category && tech.label === 'Additional familiarity') ? `<p class="small">Additional familiarity: ${skills.filter(tech => tech.category === category && tech.label === 'Additional familiarity').map(tech => esc(tech.name)).join(', ')}</p>` : ''}</div>`).join('')}<div class="resume-skill-group"><h3>AI-Assisted Development Tools</h3><p>${profile.aiTools.map(tool => esc(tool.name)).join(', ')}</p></div><a class="text-link" href="/stack/">Explore Project Evidence ${icon('right')}</a></section><section class="card"><h2>Contact</h2><p>${esc(profile.location)}</p><a class="resume-email" href="mailto:${esc(profile.email)}">${esc(profile.email)}</a><a class="text-link" href="https://github.com/${esc(profile.github)}">GitHub ${icon('arrow')}</a></section></aside></div></article>`;
}

function stackPage(technologies, projects) {
  const categories = [...new Set(technologies.map(tech => tech.category))];
  return `${intro('Tools, with<br>Context.', 'A practical stack for web applications, native Android, and the work around them.')}<section data-filter-group="technologies">${filterControls(categories, 'technologies')}${categories.map(category => `<section class="stack-category-group"><h2>${esc(category)}</h2><div class="stack-grid">${technologies.filter(tech => tech.category === category).map(tech => `<article class="stack-card card" data-filter-item data-item-category="${esc(tech.category)}" data-search="${esc(`${tech.name} ${tech.category} ${tech.description}`)}"><div class="stack-title">${brand(tech.iconId || tech.id, tech.monochrome || Boolean(tech.iconId))}<h3>${esc(tech.name === 'Node test runner' ? 'Node Test Runner' : tech.name)}</h3></div><p>${esc(tech.description)}</p><div class="stack-evidence"><span>${esc(evidenceLabels[tech.label] || tech.label)}</span>${tech.projects.map(id => `<a href="/projects/${id}/">${esc(projects.find(project => project.id === id).title)}${icon('arrow')}</a>`).join('')}${!tech.projects.length ? `<a href="${esc(tech.evidenceUrl || 'https://github.com/Eyzen08/Portfolio')}">${tech.evidenceUrl ? 'Résumé Skills' : 'Portfolio Source'}${icon('arrow')}</a>` : ''}</div></article>`).join('')}</div></section>`).join('')}${emptyState}</section>`;
}

function contact(profile, withIntro = true) {
  return `${withIntro ? intro('Let’s Build Something Useful.', 'Have a software development opportunity or project in mind? I’d like to hear about it.') : ''}<div class="contact-layout"><section class="contact-info card"><p class="eyebrow">Direct contact</p><h2>Reach Out</h2><a class="contact-email" href="mailto:${esc(profile.email)}">${esc(profile.email)}</a><button type="button" class="text-button" data-copy-email="${esc(profile.email)}">${icon('copy')}Copy Email Address</button><p class="small" data-copy-status role="status"></p><p>${esc(profile.location)}</p><div class="social-list">${profile.socials.map(social => `<a href="${esc(social.url)}">${brand(social.id, ['github', 'instagram'].includes(social.id))}<span>${esc(social.label)}</span>${icon('arrow')}</a>`).join('')}</div><p class="muted">${esc(profile.workWithMe)}</p></section><form class="contact-form card" data-contact-form action="${esc(profile.formspree)}" method="POST"><p class="eyebrow">Get in touch</p><h2>Let’s Build Something</h2><div class="field"><label for="contact-name">Name</label><input id="contact-name" name="name" autocomplete="name" required maxlength="100" placeholder="Your Name"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></div><div class="field"><label for="contact-message">Message</label><textarea id="contact-message" name="message" required minlength="10" maxlength="5000" rows="6" placeholder="Tell me about the opportunity or project…"></textarea></div><div class="honeypot" aria-hidden="true"><label for="contact-extra">Leave This Field Empty</label><input id="contact-extra" name="_gotcha" tabindex="-1" autocomplete="off"></div><button class="button primary" type="submit">Send Inquiry ${icon('right')}</button><p class="form-status" data-form-status role="status"></p><p class="small muted">Your inquiry is processed by Formspree. Direct email is also available.</p></form></div>`;
}

function mediaImage(item, extra = '') {
  return `<img src="${esc(item.src)}" width="${item.width}" height="${item.height}" alt="${esc(item.alt)}" loading="lazy" ${extra}>`;
}

function movingStrip(technologies) {
  return `<div class="tool-window" data-moving-strip><div class="tool-track"><ul class="bento-tools" aria-label="Project-backed technologies">${['react', 'nodejs', 'postgresql', 'java', 'android', 'git', 'vite'].map(id => { const tech = technologies.find(item => item.id === id); return tech ? `<li><a href="/stack/">${brand(id)}<span>${esc(tech.name)}</span></a></li>` : ''; }).join('')}</ul><ul class="bento-tools" aria-hidden="true">${['react', 'nodejs', 'postgresql', 'java', 'android', 'git', 'vite'].map(id => { const tech = technologies.find(item => item.id === id); return tech ? `<li><span class="tool-label">${brand(id)}<span>${esc(tech.name)}</span></span></li>` : ''; }).join('')}</ul></div></div>`;
}
function profileGallery(profile) {
  const gallery = profile.gallery;
  return `<figure class="bento-photo card card--media" data-gallery aria-label="Personal photo gallery">${gallery.map((item,index) => `<div data-gallery-frame>${index === 0 ? portrait(profile, true) : mediaImage(item)}</div>`).join('')}${gallery.length > 1 ? '<div class="gallery-controls" data-gallery-controls hidden><button type="button" data-gallery-prev aria-label="Previous personal photo">←</button><button type="button" data-gallery-next aria-label="Next personal photo">→</button></div><figcaption class="sr-only" data-gallery-caption aria-live="polite"></figcaption>' : ''}</figure>`;
}
function backgroundDeck(profile, projects) {
  const education = profile.education[0];
  const highlights = [
    { id: 'background-education', label: 'Education', text: `${education.title} at ${education.organization}. ${education.period}.`, href: '/resume/#education', images: [education.preview] },
    { id: 'background-leadership', label: 'Project Leadership', text: 'STI Vio-Log: full-stack lead and primary system developer. Kwiztorya: lead programmer of a three-member team. Both academic projects.', href: '/projects/', images: projects.map(project=>project.previewScreens[0]) },
    { id: 'background-training', label: 'Training', text: `${profile.certifications.length} training and certification entries across AI, cybersecurity, software development, and robotics.`, href: '/training/', images: profile.certifications.filter(item=>item.preview).slice(0,2).map(item=>item.preview) }
  ];
  return `<section class="bento-background card" data-background-deck data-deck data-deck-kind="background" aria-label="Background highlights"><p class="deck-hint">A Little Background</p><div class="background-deck" data-deck-stage>${highlights.map(item => `<article class="background-card" id="${item.id}" data-background-card data-deck-card><div class="background-paper"><h3>${esc(item.label)}</h3><div class="background-preview ${item.id}">${item.images.map(image=>mediaImage(image)).join('')}</div><div id="${item.id}-text" data-deck-caption><p>${esc(item.text)}</p><a href="${item.href}" class="text-link">Read More ${icon('arrow')}</a></div></div></article>`).join('')}</div><div class="background-controls" data-deck-controls hidden><div class="picture-selectors" role="group" aria-label="Choose background highlight">${highlights.map((item,index)=>`<button type="button" data-deck-select data-deck-index="${index}" aria-pressed="${index===0}" aria-controls="${item.id}-text">${esc(item.label)}</button>`).join('')}</div><span class="sr-only" data-deck-counter role="status"></span></div></section>`;
}
function locationCard(profile) {
  return `<section class="bento-location card" aria-label="Location"><div data-location-map><div class="location-map" data-map-canvas hidden></div><p class="map-status" data-map-status>Explore Taguig City with an interactive map.</p></div><div class="location-caption"><h2>${esc(profile.location)}</h2><p>Philippine Standard Time · UTC+8</p><a class="text-link" href="https://www.openstreetmap.org/#map=12/14.52/121.05" target="_blank" rel="noopener noreferrer">Open Full Map ${icon('arrow')}<span class="sr-only"> on OpenStreetMap (opens in a new tab)</span></a></div></section>`;
}
function sphereSection(technologies, profile) {
  const skills = technologies.filter(tech => tech.name !== 'Node test runner');
  const categories = ['Frontend','Backend','Databases','Mobile Development','Programming Languages','Security','Tools and Workflow','Deployment and DevOps'];
  return `<section class="section sphere-section" id="skills" data-sphere>${sectionTitle('Tech Stack','Tech Stack')}${movingStrip(technologies)}<div class="skills-layout"><div class="sphere-presentation" data-sphere-presentation hidden><canvas width="640" height="520" aria-hidden="true"></canvas><p class="sphere-name" data-sphere-name>Explore the Technologies</p></div><div class="skill-categories" id="sphere-evidence" aria-label="Technical skills">${categories.map(category=>{
    const group=skills.filter(tech=>tech.category===category);
    return `<section class="skill-group"><h3>${esc(category)}</h3>${[false,true].map(familiar=>{const items=group.filter(tech=>(tech.label==='Additional familiarity')===familiar);return items.length?`${familiar?'<p class="familiar-label">Familiar languages</p>':''}<ul class="sphere-evidence">${items.map(tech=>`<li${tech.projects.length?` data-sphere-item data-name="${esc(tech.name)}"`:''}><a href="${tech.projects.length?`/projects/${esc(tech.projects[0])}/`:'/resume/#skills'}">${brand(tech.iconId||tech.id,tech.monochrome||Boolean(tech.iconId))}<span>${esc(tech.name)}</span></a></li>`).join('')}</ul>`:'';}).join('')}</section>`;
  }).join('')}<section class="skill-group skill-ai"><h3>AI &amp; Learning</h3><ul class="ai-tool-list">${profile.aiTools.map(tool=>`<li><img src="${esc(tool.logo)}" width="22" height="22" alt="" loading="lazy"><span>${esc(tool.name)}</span></li>`).join('')}</ul><p class="small muted">I review and validate the code I use.</p><a class="text-link" href="#ai">My approach ${icon('arrow')}</a></section><a class="text-link" href="/stack/">Explore project evidence ${icon('arrow')}</a></div></div></section>`;
}

function projectFeature(project, technologies, index, browse = false) {
  const previewAttributes=project.id==='sti-vio-log'?`data-details-open data-project-id="${project.id}" aria-controls="project-details-viewer" aria-haspopup="dialog"`:`data-preview-open aria-controls="preview-${project.id}" aria-haspopup="dialog"`;
  const search=[project.title,project.summary,project.role,...project.technologies.map(id=>technologies.find(tech=>tech.id===id)?.name||id)].join(' ');
  const filters=browse?` data-filter-item data-item-category="${project.platform.toLowerCase()}" data-search="${esc(search)}"`:'';
  const heading=browse?'h2':'h3';
  const category=project.platform==='Web'?'Full-Stack Web Application':'Android Application';
  return `<article class="${browse?'project-card card project-feature':'project-feature card'}" data-project-preview${project.id==='kwiztorya'?' data-screenshot-preview':''}${filters}><a class="project-screenshot-link" href="${esc(project.previewScreens[0].src)}" aria-label="Preview ${esc(project.title)} Screenshots" ${previewAttributes}><span class="showcase-cover${project.id==='sti-vio-log'?' showcase-cover-sti':''}">${screenImage(project.previewScreens[0],false,true)}</span>${index===0?'<span class="featured-badge"><i aria-hidden="true"></i> Featured</span>':''}<span class="preview-affordance" aria-hidden="true">${icon('arrow')}</span></a><div class="project-feature-copy"><p class="project-category"><span>0${index+1}</span> ${esc(category)}</p><${heading}><a href="/projects/${project.id}/">${esc(project.title)}</a></${heading}><p class="project-role">${esc(project.year)} · ${esc(project.role)}</p><p class="project-summary">${esc(project.summary)}</p>${tagList(project.cardTechnologies,technologies,true)}<p class="project-status">${esc(project.status)}</p><details class="project-more"><summary>Contributions &amp; features <span aria-hidden="true">+</span></summary><p>${esc(project.category)}</p><p>${esc(project.context)}</p><p>${esc(project.contribution)}</p><ul class="project-features">${project.features.map(feature=>`<li>${esc(feature)}</li>`).join('')}</ul>${tagList(project.technologies,technologies)}</details><div class="actions">${button(project.previewScreens[0].src,'View Project',false,previewAttributes)}<a class="text-link" href="/projects/${project.id}/">Case Study ${icon('arrow')}</a><a class="text-link" href="${esc(project.sourceUrl)}">Source ${icon('arrow')}</a>${project.liveUrl?`<a class="text-link" href="${esc(project.liveUrl)}">Live App ${icon('arrow')}</a>`:''}</div></div>${project.id==='kwiztorya'?projectViewer(project):''}</article>`;
}

function certificatePreview(item) {
  if(!item.preview)return `<div class="certificate-placeholder"><span aria-hidden="true">${icon('download')}</span><p>Certificate preview unavailable</p></div>`;
  const kind=item.documentUrl.endsWith('.pdf')?'PDF':'Image';
  return `<a class="certificate-preview" href="${esc(item.preview.src)}" target="_blank" rel="noopener noreferrer" data-certificate-open data-certificate-title="${esc(item.title)}" aria-label="Preview ${esc(item.title)} certificate (opens image in a new tab)"><img src="${esc(item.preview.src)}" width="${item.preview.width}" height="${item.preview.height}" alt="${esc(item.preview.alt)}" loading="lazy"><span>Preview Certificate ${icon('arrow')}</span></a><a class="certificate-original text-link" data-certificate-original data-document-kind="${kind}" href="${esc(item.documentUrl)}" target="_blank" rel="noopener noreferrer">Open Original ${kind}<span class="sr-only"> (opens in a new tab)</span> ${icon('arrow')}</a>`;
}

function certificateViewer(certifications) {
  const first=certifications.find(item=>item.preview);
  if(!first)return '';
  return `<dialog class="certificate-viewer" id="certificate-viewer" data-certificate-viewer aria-labelledby="certificate-viewer-title"><header class="preview-header"><h2 id="certificate-viewer-title" data-certificate-title>Certificate Preview</h2><button class="icon-button" type="button" data-certificate-close aria-label="Close Certificate Preview" autofocus>✕</button></header><div class="certificate-body"><img class="certificate-full-image" data-certificate-image src="${esc(first.preview.src)}" width="${first.preview.width}" height="${first.preview.height}" alt="${esc(first.preview.alt)}"><p data-certificate-error role="status" hidden>Certificate preview unavailable. You can open the original document below.</p><a class="button" data-certificate-document href="${esc(first.documentUrl)}" target="_blank" rel="noopener noreferrer">Open Original PDF<span class="sr-only"> (opens in a new tab)</span> ${icon('arrow')}</a></div></dialog>`;
}

function homeTraining(profile) {
  const recent=profile.certifications.filter(item=>item.period!=='June 2018').sort((a,b)=>Number(Boolean(b.preview))-Number(Boolean(a.preview)));
  const earlier=profile.certifications.filter(item=>item.period==='June 2018');
  const card=item=>`<article class="home-certificate card">${certificatePreview(item)}<h3>${esc(item.title)}</h3><p class="certificate-meta">${item.organization?`${esc(item.organization)} · `:''}${esc(item.period)}</p></article>`;
  return `<section class="section home-training" id="training">${sectionTitle('Certificates','Credentials')}<div class="certificate-group-heading"><p class="eyebrow">Professional development · 6 entries</p><a class="text-link" href="/training/">All Training ${icon('arrow')}</a></div><div class="home-certificates" tabindex="0" role="region" aria-label="Recent certificates, scroll horizontally">${recent.map(card).join('')}</div><p class="scroll-hint">Scroll to explore all six entries ↔</p><div class="earlier-training"><p class="eyebrow">Earlier training · 2018</p>${earlier.map(card).join('')}</div>${certificateViewer(profile.certifications)}</section>`;
}

function homePage(profile, projects, technologies) {
  const formal=profile.heroPortrait;
  return `<div data-home id="top">
    <section class="portfolio-hero" aria-labelledby="hero-name"><div class="hero-stage">
      <header class="hero-heading"><p>Hi, I’m</p><h1 id="hero-name" aria-label="${esc(profile.name)}"><span>EJ Christian</span><span>Medilo</span></h1></header>
      <figure class="hero-portrait bento-photo card card--media" data-gallery aria-label="Personal photo gallery"><img class="hero-formal-portrait" src="${esc(formal.src)}" width="${formal.width}" height="${formal.height}" alt="${esc(formal.alt)}" fetchpriority="high"></figure>
      <div class="hero-copy"><h2>${esc(profile.role)}</h2><p class="hero-specialties">Full-Stack Web Development<br>Exploring AI Engineering</p><p>${esc(profile.intro)}</p><div class="actions">${button('#projects','Explore Projects',true)}<a class="hero-about-link" href="#about">About Me ${icon('arrow')}</a></div></div>
      <nav class="hero-socials" aria-label="Social links"><a href="https://github.com/${esc(profile.github)}">${brand('github',true)} GitHub</a><a href="mailto:${esc(profile.email)}">${icon('mail')} Email</a><a href="${esc(profile.resumePdf)}" target="_blank" rel="noopener noreferrer">${icon('download')} Résumé</a><a href="#contact">${icon('arrow')} Contact Me</a></nav>
      <a class="hero-scroll" href="#about" aria-label="Scroll to about"><span class="scroll-mouse" aria-hidden="true"></span><span>Scroll</span></a>
    </div><div class="hero-facts"><div><strong>02</strong><span>Academic projects</span></div><div><strong>BSIT</strong><span>Fourth-year student</span></div><div><strong>PH</strong><span>Taguig City, Philippines</span></div></div></section>
    <section class="section about-section" id="about">${sectionTitle('About','About Me')}<div class="summary-grid"><section class="summary-about"><p class="eyebrow">— My journey</p><h3>Building practical<br>software with purpose.</h3><p>${esc(profile.aboutSummary)}</p><p>${esc(profile.goal)}</p><p class="professional-positioning">${esc(profile.positioning)}</p><p class="eyebrow expertise-label">Expertise</p><ul class="expertise-list"><li>Full-stack web development</li><li>Android applications</li><li>API integration</li><li>Application security</li></ul><a class="text-link" href="/about/">More About Me ${icon('arrow')}</a></section><section class="about-education" id="education"><p class="eyebrow">— Education</p>${timeline(profile.education,3)}${mediaImage(profile.education[0].preview)}<a class="text-link" href="/resume/">View Résumé ${icon('arrow')}</a></section></div><details class="about-extras"><summary>Explore my background and location <span aria-hidden="true">+</span></summary><div class="about-context">${locationCard(profile)}${backgroundDeck(profile,projects)}</div></details></section>
    ${sphereSection(technologies,profile)}
    <section class="section featured-section" id="projects">${sectionTitle('Projects','Projects')}<div class="project-section-bar"><p>Selected <sup>02</sup></p><a class="text-link" href="/projects/">All Projects ${icon('arrow')}</a><span>Selected academic work</span></div><div class="featured-grid">${projects.map((project,index)=>projectFeature(project,technologies,index)).join('')}</div></section>
    <section class="section home-background" id="experience">${sectionTitle('Experience','Experience')}<p class="experience-context">Student training &amp; work immersion</p><div class="experience-list">${profile.experience.map((item,index)=>`<details name="experience-rows" class="experience-row"><summary><span class="experience-number">0${index+1}</span><span class="experience-identity"><span class="experience-organization">${esc(item.organization)}</span><span class="experience-role">${esc(item.title)}</span></span><span class="experience-year">${esc(item.period)}</span><span class="experience-plus" aria-hidden="true">+</span></summary><div class="experience-description"><p>${esc(item.location)}</p><ul class="experience-bullets">${item.bullets.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></div></details>`).join('')}</div><a class="text-link" href="/resume/">Full Résumé ${icon('arrow')}</a></section>
    ${homeTraining(profile)}
    <section class="section home-ai" id="ai" aria-labelledby="ai-title">${sectionTitle('Workflow','My Process')}<div class="workflow-grid"><article><span class="workflow-number">01</span><h3>Plan &amp; understand</h3><p>${esc(profile.aiApproach)}</p></article><article><span class="workflow-number">02</span><h3>Build &amp; learn</h3><p>${esc(profile.aiLearning)}</p><p>AI tools assist my work; I stay responsible for the implementation.</p></article><article><span class="workflow-number">03</span><h3>Review &amp; validate</h3><p>I review and test AI-generated suggestions rather than assuming they are correct. I work to understand the code and validate its behavior.</p></article></div><h3 id="ai-title">AI Tools I Use</h3><ul class="ai-tool-list">${profile.aiTools.map(tool=>`<li><img src="${esc(tool.logo)}" width="26" height="26" alt="" loading="lazy"><span>${esc(tool.name)}</span></li>`).join('')}</ul></section>
    <section class="section home-activity" id="github">${sectionTitle('Activity','In Public')}${githubBlock(true)}</section>
    <section class="section home-contact" id="contact"><div class="contact-next">${sectionTitle('Let’s Build Together','Let’s Build Together')}<div class="next-step-grid">${[
      ['mail','Share the opportunity','Tell me about the role, project, or idea you have in mind.','Start a conversation'],
      ['right','Talk through the details',"Let's discuss the goals, requirements, and how I could contribute.",'Understand the scope'],
      ['code','Build & experiment','I enjoy turning ideas into working projects through hands-on web and Android development.','Explore my projects'],
      ['brain','Explore artificial intelligence',"I'm learning about AI, exploring new tools, and discovering how they can solve real-world problems.",'Discover my AI journey'],
      ['network','Dive into AI engineering',"I'm exploring how AI models, APIs, and intelligent features can be integrated into useful applications.",'Explore what’s possible'],
      ['growth','Build & grow together',"I'm ready to learn, take on new challenges, and collaborate on projects that help me grow as a developer.",'Let’s move forward']
    ].map(([symbol,title,text,label],index)=>`<article><span class="step-symbol" aria-hidden="true">${icon(symbol)}</span><span class="step-number">0${index+1}</span><h3>${esc(title)}</h3><p>${esc(text)}</p><span class="step-label">${esc(label)}</span></article>`).join('')}</div></div>${contact(profile,false)}</section>
  </div>`;
}

function trainingPage(profile) {
  const certifications = profile.certifications;
  return `${intro('Training &amp;<br>Certifications.', 'Learning across software development, AI, cybersecurity, and robotics.')}<section class="certification-grid" aria-label="Training and certifications">${certifications.map(item => `<article class="certification-card card">${certificatePreview(item)}<div class="certificate-details"><p class="certificate-meta">${item.organization ? `${esc(item.organization)} <span aria-hidden="true">·</span> ` : ''}${esc(item.period)}</p><h2>${esc(item.title)}</h2></div></article>`).join('')}</section>${certificateViewer(certifications)}`;
}

export function renderPages(context) {
  const { profile, projects, technologies } = context;
  const contactCta = `<section class="contact-cta card" id="contact"><div><h2>Good Work Starts with a Conversation.</h2><p>${esc(profile.workWithMe)}</p></div>${button('/contact/', 'Get in Touch', true)}</section>`;
  const pages = [
    { route: '/', title: `${profile.name} — ${profile.positioning}`, description: profile.summary, content: homePage(profile, projects, technologies) },
    { route: '/about/', title: 'About — EJ Christian Medilo', description: profile.positioning, content: `${intro('About Me', profile.aboutSummary)}<div class="about-intro"><div class="about-portrait card"><button class="about-photo-swap" type="button" data-portrait-swap aria-label="Show formal portrait of EJ Christian Medilo" aria-pressed="false" disabled>${portrait(profile)}<img class="portrait-swap-formal" data-formal-portrait src="${esc(profile.heroPortrait.src)}" width="${profile.heroPortrait.width}" height="${profile.heroPortrait.height}" alt="" aria-hidden="true" loading="lazy"></button><p>${esc(profile.name)}</p><span>${esc(profile.location)}</span></div><section class="card"><h2>${esc(profile.aboutIntroHeading)}</h2><p class="professional-positioning">${esc(profile.positioning)}</p><p>${esc(profile.aboutIntroText)}</p><p>${esc(profile.goal)}</p><p>${esc(profile.workWithMe)}</p></section></div><section class="section"><h2>How I Work</h2><div class="strength-grid">${profile.strengths.map(strength => `<article class="card"><h3>${esc(strength.title)}</h3><p>${esc(strength.text)}</p></article>`).join('')}</div></section><div class="personal-grid section"><section class="card"><span class="personal-symbol" aria-hidden="true">✳</span><h2>How I Use AI</h2><p>${esc(profile.aiApproach)}</p><p>I review and test AI-generated suggestions rather than assuming they are correct. I work to understand the code, validate its behavior, and take responsibility for the final implementation.</p></section><section class="card"><span class="personal-symbol" aria-hidden="true">◈</span><h2>Learning AI Engineering</h2><p>${esc(profile.aiLearning)}</p></section></div>${contactCta}` },
    { route: '/projects/', title: 'Projects — EJ Christian Medilo', description: 'Explore STI Vio-Log and Kwiztorya: roles, architecture, implementation, and lessons.', content: `<div class="projects-page">${intro('Projects', 'Explore the screenshots, my role, and the software behind each project.')}<section class="projects-browser" data-filter-group="projects">${filterControls(['Web', 'Mobile'], 'projects')}<div class="project-grid" data-project-grid>${projects.map((project,index)=>projectCard(project,technologies,index)).join('')}</div>${emptyState}</section>${contactCta}</div>` },
    { route: '/stack/', title: 'Tech Stack — EJ Christian Medilo', description: 'Technologies connected to verified project experience and résumé skills.', content: stackPage(technologies, projects) },
    { route: '/activity/', title: 'GitHub Activity — EJ Christian Medilo', description: 'Public GitHub Activity and source repositories for Eyzen08.', content: `${intro('The Work<br>Continues.', 'Explore the public repositories and contribution history behind the projects.')}${githubBlock()}<section class="section"><h2>Start with the Source</h2><div class="repository-list">${projects.map(project => `<a class="card" href="${esc(project.sourceUrl)}">${brand('github', true)}<div><h3>${esc(project.title)}</h3><p>${esc(project.summary)}</p></div>${icon('arrow')}</a>`).join('')}</div></section>` },
    { route: '/training/', title: 'Training & Certifications — EJ Christian Medilo', description: 'Certificates and professional development in software, AI, cybersecurity, and robotics.', content: trainingPage(profile) },
    { route: '/resume/', title: 'Résumé — EJ Christian Medilo', description: 'Professional Summary, experience, education, and selected development work.', content: resumePage(profile, projects, technologies) },
    { route: '/contact/', title: 'Contact — EJ Christian Medilo', description: 'Contact EJ about a software development opportunity, project, or collaboration.', content: contact(profile) },
    ...projects.map(project => ({ route: `/projects/${project.id}/`, title: `${project.title} — Case Study`, description: project.summary, content: caseStudy(project, technologies) })),
    { route: '/404.html', title: 'Page Not Found — EJ Christian Medilo', description: 'Find your way back to EJ’s portfolio.', content: `${intro('This Page Took<br>a Different Path.', 'The address may have changed. Explore the projects or return to the homepage.')}<div class="actions">${button('/', 'Back to Home', true)}${button('/projects/', 'Explore Projects')}</div>` }
  ];
  for (const page of pages) if (page.route === '/' || page.route === '/projects/') page.content += projectDetailsViewer(projects, technologies);
  return pages;
}

export function shell(page, { profile, release, origin }) {
  const navigation = [['/', 'Home'], ['/about/', 'About'], ['/projects/', 'Projects'], ['/stack/', 'Skills'], ['/training/', 'Training'], ['/resume/', 'Resume'], ['/contact/', 'Contact']];
  const headerNavigation = page.route === '/' ? [['#about', 'About'], ['#skills', 'Tech Stack'], ['#projects', 'Projects'], ['#experience', 'Experience'], ['#contact', 'Contact']] : navigation;
  const active = href => href === '#top' ? page.route === '/' : href.startsWith('#') ? false : href === '/' ? page.route === '/' : page.route.startsWith(href);
  const schema = JSON.stringify({ '@context': 'https://schema.org', '@type': 'Person', name: profile.name, url: origin || undefined, sameAs: profile.socials.map(social => social.url), email: profile.email }).replaceAll('<', '\\u003c');
  return `<!doctype html><html lang="en"${page.route === '/' ? ' class="home-page"' : ''}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(page.title)}</title><meta name="description" content="${esc(page.description)}"><meta name="robots" content="${release && page.route !== '/404.html' ? 'index,follow' : 'noindex,nofollow'}"><meta name="theme-color" content="#fdfdfc"><meta property="og:type" content="website"><meta property="og:title" content="${esc(page.title)}"><meta property="og:description" content="${esc(page.description)}">${origin ? `<link rel="canonical" href="${esc(origin + page.route)}"><meta property="og:url" content="${esc(origin + page.route)}"><meta property="og:image" content="${esc(origin)}/assets/brand/social-preview.png"><meta name="twitter:card" content="summary_large_image">` : ''}<link rel="icon" href="/assets/brand/favicon-32.png" type="image/png" sizes="32x32"><link rel="icon" href="/assets/brand/favicon-48.png" type="image/png" sizes="48x48"><link rel="preload" href="/assets/fonts/inter-latin-variable.woff2" as="font" type="font/woff2" crossorigin><script src="/assets/theme-init.js"></script><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/redesign.css"><link rel="stylesheet" href="/assets/motion.css"><link rel="preload" href="/assets/fonts/archivo-variable.ttf" as="font" type="font/ttf" crossorigin>${page.route==='/' ? '<link rel="stylesheet" href="/assets/vendor/maplibre/maplibre-gl.css">' : ''}<script type="module" src="/assets/app.js"></script><script type="application/ld+json">${schema}</script></head><body><a class="skip-link" href="#main">Skip to Content</a><header class="site-header"><div class="header-inner"><div class="header-left"><a class="wordmark" href="/" aria-label="EJ Medilo home">${wordmark()}</a><a class="availability-pill" href="/contact/"><i aria-hidden="true"></i><span class="availability-desktop">Open to Opportunities</span><span class="availability-mobile">Available for Work</span></a></div><div class="header-actions"><button class="icon-button theme-toggle" type="button" data-theme-toggle aria-label="Switch Theme"><span class="sun-icon">${icon('sun')}</span><span class="moon-icon">${icon('moon')}</span></button><a class="button header-contact" href="/contact/">Let’s Talk ${icon('arrow')}</a><button class="icon-button menu-button" type="button" data-menu-button aria-controls="main-navigation" aria-expanded="false" aria-label="Toggle Navigation" hidden>${icon('menu')}</button></div><nav class="main-nav" id="main-navigation" data-menu aria-label="${page.route === '/' ? 'Portfolio sections' : 'All pages'}">${headerNavigation.map(([href,label]) => `<a href="${href}" ${active(href) ? 'aria-current="page"' : ''} ${href.startsWith('#') ? `data-section-link="${href.slice(1)}"` : ''}>${label}</a>`).join('')}</nav></div></header><main class="container ${page.route.startsWith('/projects/') && page.route !== '/projects/' ? 'case-page' : ''}" id="main">${page.content}</main><footer class="site-footer"><div class="container"><div class="footer-inner"><div class="footer-identity"><a class="wordmark" href="/" aria-label="EJ Medilo home">${wordmark()}</a><p class="footer-positioning">${esc(profile.positioning)}</p><p>${esc(profile.aboutSummary)}</p>${button('/contact/','Let’s Talk',true)}</div><div><h2>Explore</h2><nav class="footer-pages" aria-label="All portfolio pages">${[...navigation, ['/activity/', 'Activity']].map(([href,label])=>`<a href="${href}">${label}</a>`).join('')}</nav></div><div class="footer-contact"><h2>Contact</h2><a href="mailto:${esc(profile.email)}">${esc(profile.email)}</a><p>${esc(profile.location)}</p></div><div><h2>Connect</h2><div class="footer-links">${profile.socials.map(social=>`<a href="${esc(social.url)}">${esc(social.label)} ${icon('arrow')}</a>`).join('')}</div></div></div><div class="footer-bottom"><p>© ${new Date().getFullYear()} ${esc(profile.name)}. All rights reserved.</p><a href="${page.route==='/'?'#top':'#main'}">Back to top ↑</a></div></div></footer></body></html>`;
}
